import hashlib,importlib.util,json
from pathlib import Path
w=Path(__file__).parent;p=w/'book/manifest.json';s=w/'book/en/short_content.html'
spec=importlib.util.spec_from_file_location('build_books','tools/build_books.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
phrases='''racial injustice|empathy|moral courage|education|cultural memory|fictional town|prejudice|institutions|ordinary relationships|defense of Tom Robinson|justice demands|children learn social rules|discrimination|listening across differences|noticing bias|unfair systems|vulnerable people|racial hierarchy|formal legal procedures|unequal outcomes|courtroom|stereotypes|testimony|policing|sentencing|employment|opportunity|racism|individual hostility|unequal treatment|public awareness|dialogue|civic action|policies|social cost|acting on principle|point of view|practical discipline|honest conversation|rumor|neighbor’s humanity|community dialogue|legal system|decisions and behavior|classroom discussions|historical context|legal ideals|lived experience|critical questions|present-day evidence|shared story|test their assumptions|local projects|public advocacy|painful histories|moral lesson|adaptations|film portrayal|theatrical interpretations|contemporary writing|innocence|moral responsibility|retelling|Tom Robinson’s experience|racial order|Whose voice receives attention|media and art|diverse perspectives|cultural admiration|protect vulnerable people|children’s learning|novel’s afterlife|relationships|cultural conversations|trial|evidence|verdict|legal procedures|social rules|film|stories|Maycomb|Atticus Finch|Scout|Jem|Boo Radley’s life|Tom Robinson|classroom|students|teachers'''.split('|')
norm=m.keyword_normalise(m.keyword_source_text(s));missing=[x for x in phrases if m.keyword_normalise(x) not in norm]
print('count',len(phrases),'distinct',len(set(phrases)),'missing',missing)
if len(phrases)!=90 or len(set(phrases))!=90 or missing:raise SystemExit(1)
d=json.loads(p.read_text());d['keywordReview']={'sourceHash':hashlib.sha256(s.read_bytes()).hexdigest(),'phrases':phrases,'status':'reviewed-source-grounded'}
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
